function get_exam_questions(string $type = 'professional'): array
{
    $normalizedType = strtolower(trim($type));
    if (!in_array($normalizedType, ['professional', 'subprofessional', 'complete'], true)) {
        $normalizedType = 'complete';
    }

    return [
        'type' => $normalizedType,
        'title' => 'Philippines Civil Service Exam Complete Reviewer',
        'timeLimitMinutes' => $normalizedType === 'professional' ? 190 : 160,
        'passingPercent' => 80,
        'source' => 'index(4).pdf',
        'descriptiveInstructions' => 'Supply the information as honestly and accurately as possible. Descriptive responses are confidential and are not scored.',
        'descriptiveQuestionnaire' => get_descriptive_questionnaire(),
        'contexts' => get_reviewer_contexts(),
        'media' => get_reviewer_media(),
        'categories' => complete_question_categories(),
        'scoredQuestionCount' => 210,
        'descriptiveQuestionCount' => 20,
    ];
}

function category_definitions(string $type = 'complete'): array
{
    return array_map(
        static fn(array $category): array => [
            $category['key'],
            $category['title'],
            $category['group'],
            $category['itemCount'],
        ],
        complete_question_categories()
    );
}

